"use client";
import { motionTokens, useShouldReduceMotion } from "../utils/motion/index.js";
import * as React from "react";
import { animate, motionValue } from "motion/react";
//#region src/internal/progress.ts
const PROGRESS_TRANSITION = motionTokens.spring.progress;
const VALUE_TRANSITION = PROGRESS_TRANSITION;
function useCountingNumber(target, transition, from = 0) {
	const [shown, setShown] = React.useState(from);
	const [value] = React.useState(() => motionValue(from));
	const reduce = useShouldReduceMotion();
	const transitionRef = React.useRef(transition);
	React.useLayoutEffect(() => {
		transitionRef.current = transition;
	});
	React.useEffect(() => value.on("change", setShown), [value]);
	React.useEffect(() => {
		if (reduce) {
			value.jump(target);
			return;
		}
		let controls;
		const timeout = setTimeout(() => {
			controls = animate(value, target, transitionRef.current);
		}, 0);
		return () => {
			clearTimeout(timeout);
			controls?.stop();
		};
	}, [
		value,
		target,
		reduce
	]);
	return shown;
}
//#endregion
export { PROGRESS_TRANSITION, VALUE_TRANSITION, useCountingNumber };
